<script setup lang="ts">import {ref,computed} from 'vue';import type {ReconcileResult,ReconcilePoint} from '../types/domain';import {MATCH_STATUSES} from '../constants/enums';import {num} from '../utils/format';const props=defineProps<{result:ReconcileResult}>();const showEssential=ref(true),showAmbiguous=ref(true),showLeft=ref(true),showRight=ref(true),onlyNever=ref(false);
const bounds=computed(()=>{const all=[...props.result.points.left,...props.result.points.right];let x0=Math.min(...all.map(p=>p.x)),x1=Math.max(...all.map(p=>p.x)),y0=Math.min(...all.map(p=>p.y)),y1=Math.max(...all.map(p=>p.y));const pad=Math.max(x1-x0,y1-y0,1)*.08;x0-=pad;x1+=pad;y0-=pad;y1+=pad;const scale=Math.min(850/(x1-x0),385/(y1-y0)),left=75+(850-(x1-x0)*scale)/2,top=35+(385-(y1-y0)*scale)/2;return{x0,x1,y0,y1,scale,left,top}});
const sx=(x:number)=>bounds.value.left+(x-bounds.value.x0)*bounds.value.scale;const sy=(y:number)=>bounds.value.top+(bounds.value.y1-y)*bounds.value.scale;
const leftMap=computed(()=>new Map(props.result.points.left.map(p=>[p.point_id,p]))),rightMap=computed(()=>new Map(props.result.points.right.map(p=>[p.point_id,p])));
function segments(status:string){const parts:string[]=[];for(const pair of props.result.pairs){if(pair.status!==status)continue;const a=leftMap.value.get(pair.left_id),b=rightMap.value.get(pair.right_id);if(!a||!b)continue;parts.push(`M${sx(a.x).toFixed(2)} ${sy(a.y).toFixed(2)}L${sx(b.x).toFixed(2)} ${sy(b.y).toFixed(2)}`)}return parts.join('')}
const essentialPath=computed(()=>segments('essential')),ambiguousPath=computed(()=>segments('ambiguous'));
const fill=(p:ReconcilePoint)=>p.status==='always_matched'?'#52665b':p.status==='sometimes_matched'?'#b69b4f':'#a94f3d';
const shown=(p:ReconcilePoint)=>!onlyNever.value||p.status==='never_matched';
const label=(side:string,p:ReconcilePoint)=>`${side} ${p.point_id} · x=${p.x}m / y=${p.y}m · ${MATCH_STATUSES[p.status]}${p.partners.length?' · 可配 '+p.partners.length+' 个':''}`;
</script>
<template><div class="survey-plot"><div class="plot-title"><strong>对账连线 · 原始编号一一对应</strong><span>x/y同一比例 · local_m · 米 · 阈值{{result.threshold_m}}m</span></div><div class="boundary-legend"><label><input type="checkbox" v-model="showEssential" aria-label="显示必然配线"/><i style="background:#52665b"/>必然配线 {{result.essential_pair_count}}</label><label><input type="checkbox" v-model="showAmbiguous" aria-label="显示歧义配线"/><i style="border-top:2px dashed #b69b4f"/>歧义配线 {{result.ambiguous_pair_count}}</label><label><input type="checkbox" v-model="showLeft" aria-label="显示左侧点"/><i class="point-key"/>左侧 {{result.points.left.length}}</label><label><input type="checkbox" v-model="showRight" aria-label="显示右侧点"/><i style="background:#a96e48;transform:rotate(45deg);width:6px;height:6px"/>右侧 {{result.points.right.length}}</label><label><input type="checkbox" v-model="onlyNever" aria-label="只看始终未配"/><i style="background:#a94f3d"/>只看始终未配</label></div><svg viewBox="0 0 1000 490" role="img" aria-label="两点组对账连线与原始编号"><g v-for="f in [0,.25,.5,.75,1]" :key="f"><line :x1="sx(bounds.x0)" :x2="sx(bounds.x1)" :y1="sy(bounds.y0+f*(bounds.y1-bounds.y0))" :y2="sy(bounds.y0+f*(bounds.y1-bounds.y0))" stroke="#d8d0bb"/><line :x1="sx(bounds.x0+f*(bounds.x1-bounds.x0))" :x2="sx(bounds.x0+f*(bounds.x1-bounds.x0))" :y1="sy(bounds.y0)" :y2="sy(bounds.y1)" stroke="#e2dccb"/><text :x="sx(bounds.x0)-9" :y="sy(bounds.y0+f*(bounds.y1-bounds.y0))+4" text-anchor="end">{{num(bounds.y0+f*(bounds.y1-bounds.y0),2)}}</text><text :x="sx(bounds.x0+f*(bounds.x1-bounds.x0))" :y="sy(bounds.y0)+22" text-anchor="middle">{{num(bounds.x0+f*(bounds.x1-bounds.x0),2)}}</text></g><path v-if="showAmbiguous&&ambiguousPath" :d="ambiguousPath" stroke="#b69b4f" stroke-width="1" fill="none" stroke-dasharray="4 3" opacity=".55"/><path v-if="showEssential&&essentialPath" :d="essentialPath" stroke="#52665b" stroke-width="1.6" fill="none" opacity=".8"/><g v-if="showLeft"><circle v-for="p in result.points.left.filter(shown)" :key="'L'+p.point_id" :cx="sx(p.x)" :cy="sy(p.y)" r="3.4" :fill="fill(p)" :opacity="p.status==='never_matched'?1:.8" :stroke="p.status==='never_matched'?'#7c2f20':'none'" stroke-width="1"><title>{{label('左',p)}}</title></circle></g><g v-if="showRight"><path v-for="p in result.points.right.filter(shown)" :key="'R'+p.point_id" :d="`M${sx(p.x)} ${sy(p.y)-4}L${sx(p.x)+4} ${sy(p.y)}L${sx(p.x)} ${sy(p.y)+4}L${sx(p.x)-4} ${sy(p.y)}Z`" :fill="fill(p)" :opacity="p.status==='never_matched'?1:.85" :stroke="p.status==='never_matched'?'#7c2f20':'none'" stroke-width="1"><title>{{label('右',p)}}</title></path></g><text :x="sx(bounds.x0)" y="18">y / 米</text><text :x="sx(bounds.x1)" :y="sy(bounds.y0)+46" text-anchor="end">x / 米</text></svg><p class="muted">圆点=左侧测组，菱形=右侧测组；绿=必配点，金=歧义归属，红=始终未配。悬停查看原始编号与可配数；连线为能出现在任一最优方案中的配对，实线必然、虚线歧义。</p></div></template>
